-- P99-reviewed Velious content. Quest faction gates deliberately bypassed; actual faction rewards retained.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Greetings, little thing. You have entered into the great city of Kael Drakkel, home of the Kromzek as well as a few of my kind, the Kromrif. If you are to walk among my people as a peer you must prove yourself as a friend, not a foe.")
  elseif e.message:findi("prove myself") then
    e.self:Say("Leave this place then and return when you have waged war upon the Coldain. Remove their heads from their bodies and return them to me. I will spread the word of your deeds amongst my people if you do so, " .. e.other:GetCleanName() .. ".")
  elseif e.message:findi("coldain") then
    e.self:Say("The Coldain are the ice dwarves who dwell in the city of Thurgadin. They are a blight upon the land known as Velious, speaking the word of their god, Brell.")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 30081 }) then
    e.self:Say("Very good, " .. e.other:GetCleanName() .. ". Slay more of the beasts and your name will be known by all of the Kromrif!")
    e.other:AddEXP(5000)
    e.other:Faction(419, 10, 0)
    e.other:Faction(448, 8, 0)
    e.other:Faction(430, -30, 0)
    e.other:Faction(406, -17, 0)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
